const orders = $input.all().map(i => i.json);
const now = new Date();

const customerMap = {};
orders.forEach(o => {
  const email = o['Customer Email'];
  const date = new Date(o['Order Date']);
  const value = parseFloat(o['Order Value'] || 0);
  if (!email) return;
  if (!customerMap[email]) {
    customerMap[email] = { email, name: o['Customer Name'], orders: [], total_spent: 0 };
  }
  customerMap[email].orders.push({ date, value });
  customerMap[email].total_spent += value;
});

const customers = Object.values(customerMap).map(c => {
  const sortedOrders = c.orders.sort((a,b) => b.date - a.date);
  const recency = Math.floor((now - sortedOrders[0].date) / (1000*60*60*24));
  const frequency = c.orders.length;
  const monetary = c.total_spent / frequency;
  const months_active = Math.max(1, Math.floor((now - sortedOrders[sortedOrders.length-1].date) / (1000*60*60*24*30)));
  return { email: c.email, name: c.name, recency_days: recency, frequency, monetary: monetary.toFixed(2), total_spent: c.total_spent.toFixed(2), months_active };
});

return customers.slice(0, 50).map(c => ({ json: c }));

